    pub fn noun_scored(&self, word: &str, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (number,) {
            (Number::Plural,) => Some(0),
            _ => None,
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

